FUNCTION_BLOCK FB_S10
VAR_INPUT
    VFDFaultCode : WORD;
    VFDRun : BOOL;
    ResetBtn : BOOL;
END_VAR
VAR_OUTPUT
    AlarmLamp : BOOL := FALSE;
    TripOutput : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    ResetBtnLast : BOOL := FALSE;
    ResetRise : BOOL := FALSE;
    HeavyFault : BOOL := FALSE;
    TripDemand : BOOL := FALSE;
    LatchedFaultCode : WORD := WORD#16#0000;
END_VAR

(*
    每次调用为一个20 ms扫描周期。

    需求冲突报告（待审，不能同时满足全部原文和形式化规约）：
    1. 要求1规定轻故障不跳闸；要求4/K4规定运行中任何非零
       故障均跳闸。C1又排除了轻故障。本实现按安全优先级执行
       要求4/K4，因此运行中轻故障也触发跳闸。
    2. C2要求 TripOutput -> NOT VFDRun，但VFDRun是只读反馈。
       在运行反馈为TRUE的故障扫描中，立即跳闸必然与C2冲突；
       本块不能修改运行反馈，也不能保证其下一周期值（C7）。
    3. C10要求第0至1周期输出均无故障，与上电即存在故障时
       的立即报警/跳闸要求冲突。本实现初始化输出为无故障，
       首次调用即处理输入，不设置屏蔽故障的启动延时。
    4. C6要求所有跳闸保持到复位。本实现保持全部跳闸，
       并仅在复位上升沿且当前故障码为零时解除。
    本源码未声称已经编译验证或通过逐周期功能测试。
*)

ResetRise := ResetBtn AND NOT ResetBtnLast;
ResetBtnLast := ResetBtn;

HeavyFault :=
    (VFDFaultCode = WORD#16#0002) OR
    (VFDFaultCode = WORD#16#0003);

TripDemand :=
    HeavyFault OR
    (VFDRun AND (VFDFaultCode <> WORD#16#0000));

(* 故障置位优先；有当前故障时不允许复位。 *)
IF TripDemand THEN
    TripOutput := TRUE;

    IF HeavyFault THEN
        (* 首个重故障锁存；可替换此前锁存的非重故障码。 *)
        IF (LatchedFaultCode <> WORD#16#0002) AND
           (LatchedFaultCode <> WORD#16#0003) THEN
            LatchedFaultCode := VFDFaultCode;
        END_IF;
    ELSIF LatchedFaultCode = WORD#16#0000 THEN
        LatchedFaultCode := VFDFaultCode;
    END_IF;

ELSIF ResetRise AND (VFDFaultCode = WORD#16#0000) THEN
    TripOutput := FALSE;
    LatchedFaultCode := WORD#16#0000;
END_IF;

(* 锁存故障优先显示；未锁存时显示当前故障码。 *)
IF LatchedFaultCode <> WORD#16#0000 THEN
    Status := LatchedFaultCode;
ELSE
    Status := VFDFaultCode;
END_IF;

AlarmLamp :=
    TripOutput OR
    (VFDFaultCode <> WORD#16#0000);

END_FUNCTION_BLOCK
